class Solution:
    def numDecodings(self, s: str) -> int:
        mod = 10 ** 9 + 7

        def check1digit(c1):
            if c1 == "0":
                return 0
            if c1 == "*":
                return 9
            return 1

        def check2digit(c1, c2):
            if c1 == "*" and c2 == "*":
                return 15
            if c1 == "*":
                if c2 <= "6":
                    return 2
                else:
                    return 1
            if c2 == "*":
                if c1 == "2":
                    return 6
                elif c1 == "1":
                    return 9
                else:
                    return 0
            if c1 == '0':
                return 0
            if int(c1) * 10 + int(c2) > 26:
                return 0
            return 1

        n = len(s)
        dp = [0 for _ in range(n + 1)]
        dp[0] = 1
        for i in range(1, n + 1):
            dp[i] = dp[i - 1] * check1digit(s[i - 1])
            if i > 1:
                dp[i] += dp[i - 2] * check2digit(s[i - 2], s[i - 1])
            dp[i] = dp[i] % mod
        return dp[-1]
